def parse_host_port(url: str) -> tuple[str, int]:
    cleaned = url.split('://', 1)[-1].split('/', 1)[0]
    if ':' in cleaned:
        h, p = cleaned.split(':', 1)
        return h, int(p)
    return cleaned, 443 if url.startswith('https://') else 80

