challenges.solution_code:
def allocate_fds(events: list[tuple[str, str]], max_fds: int) -> dict:
    active = set()
    rejected = 0
    for op, name in events:
        if op == 'open':
            if name in active:
                continue
            if len(active) >= max_fds:
                rejected += 1
            else:
                active.add(name)
        elif op == 'close':
            active.discard(name)
    return {'active': sorted(active), 'rejected': rejected}

