challenges.solution_code:
def route_partition(keys: list[str], num_shards: int) -> dict[str, list[str]]:
    shards: dict[str, list[str]] = {}
    for k in keys:
        total = sum(k.encode('utf-8'))
        shard_name = f'shard-{total % num_shards}'
        shards.setdefault(shard_name, []).append(k)
    return {name: sorted(vals) for name, vals in shards.items()}

def compute_backoff_ms(attempt: int, base_ms: int = 100, max_ms: int = 2000) -> int:
    if attempt <= 0:
        return base_ms
    return min(max_ms, base_ms * (2 ** attempt))

def sanitize_profile_update(payload: dict, allowed_fields: list[str]) -> dict:
    allowed = set(allowed_fields)
    cleaned = {}
    for key, val in payload.items():
        if key not in allowed:
            continue
        if val == '' or val is None:
            continue
        if str(val) == val:
            trimmed = val.strip()
            if not trimmed:
                continue
            cleaned[key] = trimmed
        else:
            cleaned[key] = val
    return cleaned

