def authorize_token(claims: dict, required_roles: list[str], revoked_jtis: list[str], now_ts: int) -> str:
    exp = claims.get('exp', 0)
    jti = claims.get('jti', '')
    if exp <= now_ts or jti in set(revoked_jtis):
        return '401_UNAUTHORIZED'
    if claims.get('role') not in set(required_roles):
        return '403_FORBIDDEN'
    return 'OK'

def evaluate_rate_limit(timestamps: list[int], window_sec: int, max_requests: int) -> list[bool]:
    accepted: list[int] = []
    decisions: list[bool] = []
    for t in timestamps:
        cutoff = t - window_sec
        accepted = [ts for ts in accepted if ts > cutoff]
        if len(accepted) < max_requests:
            accepted.append(t)
            decisions.append(True)
        else:
            decisions.append(False)
    return decisions

