function resolveDelegatedAction(bubblingPath) {
  for (let i = 0; i < bubblingPath.length; i++) {
    const node = bubblingPath[i];
    if (node.action && !node.disabled) {
      return node.action;
    }
    if (node.stopPropagation) {
      break;
    }
  }
  return null;
}

