function scheduleEventLoop(tasks) {
  const sync = [];
  const micro = [];
  const macro = [];
  for (const t of tasks) {
    if (t.queue === 'sync') sync.push(t.id);
    else if (t.queue === 'microtask') micro.push(t.id);
    else if (t.queue === 'macrotask') macro.push(t.id);
  }
  return [...sync, ...micro, ...macro];
}

