challenges.solution_code:
function applyScoreReducer(state, action) {
  let found = false;
  const next = state.map((item) => {
    if (item.slug === action.slug) {
      found = true;
      return { ...item, score: Math.max(item.score, action.score) };
    }
    return item;
  });
  return found ? next : [...next, { slug: action.slug, score: action.score }];
}

