function computeVirtualRange(scrollTop, viewportHeight, itemHeight, totalItems, overscan) {
  const firstVisible = Math.floor(scrollTop / itemHeight);
  const visibleCount = Math.ceil(viewportHeight / itemHeight);
  const start = Math.max(0, firstVisible - overscan);
  const end = Math.min(totalItems, firstVisible + visibleCount + overscan);
  return [start, end];
}

def audit_dockerfile(lines: list[str]) -> list[str]:
    findings = set()
    has_non_root = False
    for raw in lines:
        line = raw.strip()
        upper = line.upper()
        if upper.startswith('FROM '):
            image = line.split()[1]
            if ':' not in image or image.endswith(':latest'):
                findings.add('LATEST_TAG')
        elif upper.startswith('USER '):
            usr = line.split()[1].lower()
            if usr not in ('root', '0'):
                has_non_root = True
        elif upper.startswith('ENV '):
            if 'PASSWORD' in upper or 'SECRET' in upper:
                findings.add('HARDCODED_SECRET')
    if not has_non_root:
        findings.add('ROOT_USER')
    return sorted(findings)

