def select_upstream(nodes: list[dict], max_fails: int) -> str | None:
    healthy = [n for n in nodes if n['fails'] < max_fails]
    if not healthy:
        return None
    best = min(healthy, key=lambda n: (n['active_conns'], n['name']))
    return str(best['name'])

