def compute_hpa_replicas(current_replicas: int, current_cpu_pct: float, target_cpu_pct: float, min_replicas: int, max_replicas: int) -> int:
    ratio = current_cpu_pct / target_cpu_pct
    if 0.9 <= ratio <= 1.1:
        desired = current_replicas
    else:
        raw = current_replicas * ratio
        desired = int(raw) if raw == int(raw) else int(raw) + 1
    return max(min_replicas, min(max_replicas, desired))
